<?php require dirname(__DIR__).'/includes/bootstrap.php';$slug=isset($_GET['slug'])&&is_string($_GET['slug'])?strtolower(trim($_GET['slug'])):'';$items=site_data('work-categories.json');$category=null;foreach($items as $x){if(hash_equals($x['slug'],$slug)){$category=$x;break;}}if(!$category){http_response_code(404);$page=['title'=>'Category not found','description'=>'The requested category was not found.','path'=>'work/index.php'];require dirname(__DIR__).'/includes/header.php';?><main id="main-content"><section class="pagehero shell"><h1>Category not found.</h1><a class="button" href="../index.php">Home ↗</a></section></main><?php require dirname(__DIR__).'/includes/footer.php';exit;}$page=['title'=>$category['title'].' | Work Categories','description'=>$category['summary'],'path'=>'work/category.php'];require dirname(__DIR__).'/includes/header.php';?><main id="main-content"><section class="pagehero shell"><p class="eyebrow">Work category</p><h1><?=e($category['title'])?>.</h1><p class="lede"><?=e($category['summary'])?></p></section><section class="section shell split"><div><p class="eyebrow">Overview</p><p><?=e($category['overview'])?></p><h3>Potential problem areas</h3><ul><?php foreach($category['problems'] as $v):?><li><?=e($v)?></li><?php endforeach;?></ul></div><div><h3>Technical areas</h3><div class="chips"><?php foreach($category['technical_areas'] as $v):?><span><?=e($v)?></span><?php endforeach;?></div><h3>Related domains</h3><p><?=e(implode(' · ',$category['technology_domains']))?></p><h3>Potential engagement types</h3><ul><?php foreach($category['engagements'] as $v):?><li><?=e($v)?></li><?php endforeach;?></ul><a class="button" href="../contact.php">Discuss this area ↗</a></div></section></main><?php require dirname(__DIR__).'/includes/footer.php';?>